// Toggle actionTaken for the clicked row and restore its original pendingSlaStatus when unchecked
const list = variables['553cae72-ffc2-4864-a38c-1228fa5c6049'] || [];
const targetId = context.item.data?.id;
return list.map(row => {
  if (row.id !== targetId) return row;
  const nextTaken = !row.actionTaken;
  const defaultPending = row.id === 1 ? 'Overdue 5 days' : (row.id === 3 ? 'Due in 2 days' : (row.id === 5 ? 'Due in 4 days' : 'Pending Action'));
  const defaultTaken = row.id === 4 ? 'Verified · −9% Confirmed' : (row.id === 2 ? 'In 7-Day Window (Day 5/7)' : 'In 7-Day Window (Day 1/7)');
  return {
    ...row,
    actionTaken: nextTaken,
    slaStatus: nextTaken ? (row.takenSlaStatus || defaultTaken) : (row.pendingSlaStatus || defaultPending)
  };
});

