// Compute live count of overdue critical actionables and their alerts
const list = variables['553cae72-ffc2-4864-a38c-1228fa5c6049'] || [];
const overdueItems = list.filter(item => !item?.actionTaken && item?.severity === 'critical');
const pendingItems = list.filter(item => !item?.actionTaken);
if (overdueItems.length > 0) {
  const alertSum = overdueItems.reduce((sum, item) => sum + (item?.alerts || 0), 0);
  return `⚠ ${overdueItems.length} OVERDUE (${alertSum} ALERTS FIRED) · ${pendingItems.length} OPEN`;
}
if (pendingItems.length > 0) {
  return `✓ 0 OVERDUE · ${pendingItems.length} PENDING ACTION`;
}
return '✓ ALL 5 ACTIONABLES TAKEN · 7D VERIFICATION ACTIVE';

